import{_ as o,C as r,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Project dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"master/services/project/project-management/project-dashboard.md","filePath":"master/services/project/project-management/project-dashboard.md","lastUpdated":1791902625000}'),l={name:"master/services/project/project-management/project-dashboard.md"};function h(p,e,d,c,g,m){const s=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="project-dashboard" tabindex="-1">Project dashboard <a class="header-anchor" href="#project-dashboard" aria-label="Permalink to &quot;Project dashboard&quot;">​</a></h1><p>The dashboard sums up all your work in one screen. It shows how many tasks exist, how many hours were spent, where tasks sit and who does most of the work. You filter it to look at one project, one person or one period.</p><blockquote><p><strong>In simple words:</strong> Pick filters, then read five widgets.</p></blockquote><p>Open <code>Dashboard → Project</code>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Hours need <strong>Enable Timesheets</strong> and logged time. See <a href="./../../timesheets/">Timesheets</a>. You need permission to open the page.</p></div><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><ol><li>Open <code>Dashboard → Project</code>.</li><li>Click the filter button at the top.</li><li>Choose values and apply them.</li></ol>',7)),a(s,{src:"/images1/project/pj_dashboard_filters.png",alt:"Project dashboard filter panel with Project Website Revamp, Assignees, Tags, Customer and a date range"}),e[1]||(e[1]=t('<ul><li><strong><em>Project:</em></strong> Show one project only. Example: <strong>Website Revamp</strong>.</li><li><strong><em>Assignees:</em></strong> Show tasks of chosen people.</li><li><strong><em>Tags:</em></strong> Show tasks with chosen tags.</li><li><strong><em>Customer:</em></strong> Show the work for one customer.</li><li><strong><em>Date Range:</em></strong> A start and an end date.</li></ul><p>Leave a filter empty to include everything.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2>',3)),a(s,{src:"/images1/project/pj_dashboard_full.png",alt:"Project dashboard showing the stats row, two charts and two tables for Website Revamp"}),e[2]||(e[2]=t('<h3 id="stats-overview" tabindex="-1">Stats overview <a class="header-anchor" href="#stats-overview" aria-label="Permalink to &quot;Stats overview&quot;">​</a></h3><p>Three numbers sit at the top.</p><ul><li><strong>Total Tasks:</strong> how many tasks match.</li><li><strong>Total Hours Spent:</strong> logged time.</li><li><strong>Total Time Remaining:</strong> allocated time not yet used.</li></ul><p>Each number shows a percent change against the previous period. The numbers refresh by themselves every few seconds.</p><h3 id="tasks-by-stage" tabindex="-1">Tasks by stage <a class="header-anchor" href="#tasks-by-stage" aria-label="Permalink to &quot;Tasks by stage&quot;">​</a></h3><p>A chart of tasks created in each stage, such as <strong>New</strong> or <strong>Review</strong>.</p><h3 id="tasks-by-state" tabindex="-1">Tasks by state <a class="header-anchor" href="#tasks-by-state" aria-label="Permalink to &quot;Tasks by state&quot;">​</a></h3><p>A chart of tasks per <strong>State</strong>: <strong>In Progress</strong>, <strong>Change Requested</strong>, <strong>Approved</strong>, <strong>Cancelled</strong> and <strong>Done</strong>.</p><h3 id="top-assignees" tabindex="-1">Top assignees <a class="header-anchor" href="#top-assignees" aria-label="Permalink to &quot;Top assignees&quot;">​</a></h3><p>A table with <strong>User</strong>, <strong>Hours Spent</strong> and <strong>Tasks</strong>. It shows who logged the most time. In the example, <strong>Ava Lewis</strong> and <strong>Aarav Mehta</strong> appear here.</p><h3 id="top-projects" tabindex="-1">Top projects <a class="header-anchor" href="#top-projects" aria-label="Permalink to &quot;Top projects&quot;">​</a></h3><p>A table with <strong>Project</strong>, <strong>Hours Spent</strong> and <strong>Tasks</strong>. It shows which projects use the most time.</p><h2 id="where-else-to-see-totals" tabindex="-1">Where else to see totals <a class="header-anchor" href="#where-else-to-see-totals" aria-label="Permalink to &quot;Where else to see totals&quot;">​</a></h2><p>The same stats row appears at the top of the task list. See <a href="./../task-management/task-list-views-and-filters.html">Task list, views and filters</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set a <strong>Date Range</strong> to focus on one period. The stats row then shows the change against the period before.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-project.html">Create a project</a></li><li><a href="./../../timesheets/log-time.html">Log time</a></li><li><a href="./../task-management/create-task.html">Create a task</a></li><li><a href="./">Project management</a></li></ul>',17))])}const f=o(l,[["render",h]]);export{b as __pageData,f as default};
